package com.innspark.loginmonitor.service;

/**
 * Service interface for backend CAPTCHA verification (e.g. Google reCAPTCHA).
 */
public interface CaptchaService {

    /**
     * Verifies the client-provided CAPTCHA token against the configured CAPTCHA provider.
     * When CAPTCHA is disabled, this method is a no-op.
     *
     * @param captchaToken the response token generated by the client-side CAPTCHA widget
     * @param clientIp     the remote client IP address
     * @throws com.innspark.loginmonitor.exception.InvalidCaptchaException if verification fails or token is missing
     */
    void verifyCaptcha(String captchaToken, String clientIp);

    /**
     * Checks whether CAPTCHA verification is currently enabled in application configuration.
     *
     * @return true if CAPTCHA is enabled, false otherwise
     */
    boolean isCaptchaEnabled();
}
